// Generates the question catalog from docs/cleaneh-questions.md (specification 7.7):
//
//   src/core/catalog-data.js      ids and metadata for core: questions, sets, room kinds, groups, switches
//   src/ui/i18n/catalog-en.js     question and task texts, names of room kinds and switches, in English
//   src/ui/i18n/catalog-pl.js     the same in Polish
//
//   node tools/generate-catalog.mjs
//
// The Markdown file is the single source of truth; the generated files are not edited by hand.
// A unit test checks they are up to date.

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const SOURCE = 'docs/cleaneh-questions.md';
const GENERATED = `GENERATED by tools/generate-catalog.mjs from ${SOURCE}. Do not edit by hand.`;

// Sections with room questions; each question names its set in the "Zestaw" column.
const ROOM_SECTIONS = new Set(['Przedpokój', 'Kuchnia', 'Łazienka', 'Toaleta', 'Pokój', 'Schody', 'Schowek', 'Balkon', 'Garaż', 'Ogródek']);

const GROUPS = {
  Pranie: 'LAUNDRY',
  'Komputer i drobna elektronika': 'ELECTRONICS',
  'Sprzęt do sprzątania': 'CLEANING_GEAR',
  'Klimatyzacja i powietrze': 'AIR',
  Samochód: 'CAR',
  Dziecko: 'CHILD',
  Zwierzęta: 'PETS',
};

const SETS = {
  wejście: 'ENTRY',
  korytarz: 'HALLWAY',
  kuchnia: 'KITCHEN',
  'stół jadalny': 'DINING_TABLE',
  łazienka: 'BATHROOM',
  toaleta: 'TOILET',
  'podstawa pokoju': 'ROOM_BASE',
  łóżko: 'BED',
  biurko: 'DESK',
  kanapa: 'SOFA',
  regał: 'BOOKSHELF',
  szafa: 'WARDROBE',
  schody: 'STAIRS',
  schowek: 'STORAGE',
  balkon: 'BALCONY',
  garaż: 'GARAGE',
  ogródek: 'GARDEN',
};

const FEATURES = {
  zmywarka: 'DISHWASHER',
  pranie: 'LAUNDRY',
  pralka: 'WASHING_MACHINE',
  elektronika: 'ELECTRONICS',
  komputer: 'COMPUTER',
  sprzęt: 'CLEANING_GEAR',
  robot: 'ROBOT_VACUUM',
  powietrze: 'AIR',
  klimatyzacja: 'AIR_CONDITIONER',
  nawilżacz: 'HUMIDIFIER',
  oczyszczacz: 'AIR_PURIFIER',
  samochód: 'CAR',
  dziecko: 'CHILD',
  niemowlę: 'BABY',
  zwierzę: 'PET',
  kot: 'CAT',
  pies: 'DOG',
  klatka: 'CAGE',
  akwarium: 'AQUARIUM',
};

const ROOM_KINDS = {
  Przedpokój: 'ENTRYWAY',
  Korytarz: 'HALLWAY',
  Kuchnia: 'KITCHEN',
  Spiżarnia: 'PANTRY',
  Jadalnia: 'DINING_ROOM',
  Salon: 'LIVING_ROOM',
  Pokój: 'ROOM',
  Sypialnia: 'BEDROOM',
  'Pokój dziecka': 'KIDS_ROOM',
  Gabinet: 'STUDY',
  Garderoba: 'WALK_IN_CLOSET',
  Łazienka: 'BATHROOM',
  Toaleta: 'TOILET',
  Pralnia: 'LAUNDRY_ROOM',
  Schody: 'STAIRS',
  Schowek: 'STORAGE',
  Piwnica: 'BASEMENT',
  Strych: 'ATTIC',
  Balkon: 'BALCONY',
  Taras: 'TERRACE',
  Garaż: 'GARAGE',
  Ogródek: 'GARDEN',
};

const PRIORITIES = { H: 'HYGIENE', Z: 'NORMAL' };

const STAGES = {
  start: 'START',
  bałagan: 'TIDY',
  kurz: 'DUST',
  powierzchnie: 'WIPE',
  'podłoga sucho': 'FLOOR_DRY',
  'podłoga mokro': 'FLOOR_WET',
  koniec: 'FINISH',
};

const ROMAN = { I: 1, II: 2, III: 3, IV: 4, V: 5, VI: 6, VII: 7, VIII: 8, IX: 9, X: 10, XI: 11, XII: 12 };

const NONE = new Set(['—', '-', '']);

class CatalogError extends Error {}

function fail(message) {
  throw new CatalogError(message);
}

function cells(line) {
  return line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((cell) => cell.trim());
}

function lookup(map, value, what, where) {
  if (!Object.hasOwn(map, value)) fail(`${where}: unknown ${what} '${value}'`);
  return map[value];
}

function parseSeason(value, id) {
  if (NONE.has(value)) return null;
  const parts = value.split(/[–-]/);
  if (parts.length !== 2 || !(parts[0] in ROMAN) || !(parts[1] in ROMAN)) fail(`${id}: bad season '${value}'`);
  return [ROMAN[parts[0]], ROMAN[parts[1]]];
}

function required(row, column, id) {
  const value = row[column] ?? '';
  if (NONE.has(value)) fail(`${id}: missing '${column}'`);
  return value;
}

function positiveInt(row, column, id) {
  const value = Number(required(row, column, id));
  if (!Number.isInteger(value) || value < 1) fail(`${id}: bad '${column}' '${row[column]}'`);
  return value;
}

/** Parses the catalog Markdown into questions, switches and room kinds. */
export function parse(markdown) {
  const questions = [];
  const features = [];
  const kinds = [];
  let section = null; // 'questions' | 'features' | 'kinds' | null
  let group = null;
  let header = null;

  for (const line of markdown.split(/\r?\n/)) {
    const heading = line.match(/^#{2,3} (.+)$/);
    if (heading) {
      const title = heading[1].trim();
      group = GROUPS[title] ?? null;
      if (group || ROOM_SECTIONS.has(title)) section = 'questions';
      else if (title.startsWith('Przełączniki')) section = 'features';
      else if (title === 'Rodzaje pomieszczeń') section = 'kinds';
      else section = null;
      header = null;
      continue;
    }
    if (!section || !line.startsWith('|')) continue;
    const row = cells(line);
    if (!header) {
      header = row;
      continue;
    }
    if (row.every((cell) => /^-+$/.test(cell))) continue;
    if (row.length !== header.length) fail(`row has ${row.length} cells, header ${header.length}: ${line}`);
    const r = Object.fromEntries(header.map((name, i) => [name, row[i]]));

    if (section === 'questions') {
      const id = r.ID;
      if (!/^[a-z][a-z0-9_]*$/.test(id)) fail(`bad question id '${id}'`);
      const set = r.Zestaw;
      if (group && set !== undefined) fail(`${id}: a group question has no set`);
      questions.push({
        id,
        pl: required(r, 'PL', id),
        en: required(r, 'EN', id),
        taskPl: required(r, 'Zadanie PL', id),
        taskEn: required(r, 'Zadanie EN', id),
        minutes: positiveInt(r, 'Min', id),
        days: positiveInt(r, 'Dni', id),
        priority: lookup(PRIORITIES, r.Prio, 'priority', id),
        stage: lookup(STAGES, r.Etap, 'stage', id),
        requires: NONE.has(r.Wymaga) ? null : lookup(FEATURES, r.Wymaga, 'requirement', id),
        season: parseSeason(r.Sezon ?? '—', id),
        firstSweep: r['★'] === '★',
        set: group ? null : lookup(SETS, set, 'set', id),
        group,
      });
    } else if (section === 'features') {
      const id = lookup(FEATURES, r['Przełącznik'], 'switch', 'switch list');
      const parent = r.Uwagi.match(/^pod „(.+)”$/);
      const groupOf = r.Uwagi.match(/^grupa (.+)$/);
      features.push({
        id,
        parent: parent ? lookup(FEATURES, parent[1], 'parent switch', id) : null,
        group: groupOf ? lookup(GROUPS, groupOf[1], 'group', id) : null,
        pl: r.PL,
        en: r.EN,
      });
    } else {
      kinds.push({
        id: lookup(ROOM_KINDS, r.Rodzaj, 'room kind', 'room kinds'),
        sets: r.Zestawy.split(',').map((name) => lookup(SETS, name.trim(), 'set', r.Rodzaj)),
        pl: r.Rodzaj,
        en: r['EN (roboczo)'] ?? r.EN,
      });
    }
  }

  validate(questions, features, kinds);
  return { questions, features, kinds };
}

function validate(questions, features, kinds) {
  const ids = new Set();
  for (const q of questions) {
    if (ids.has(q.id)) fail(`duplicate question id '${q.id}'`);
    ids.add(q.id);
  }
  const featureIds = new Set(features.map((f) => f.id));
  for (const id of Object.values(FEATURES)) if (!featureIds.has(id)) fail(`switch ${id} is missing from the switch list`);
  for (const f of features) {
    if (f.parent && features.findIndex((p) => p.id === f.parent) > features.indexOf(f)) fail(`${f.id}: parent comes later`);
  }
  for (const group of Object.values(GROUPS)) {
    if (!features.some((f) => f.group === group)) fail(`group ${group} has no switch`);
    if (!questions.some((q) => q.group === group)) fail(`group ${group} has no questions`);
  }
  if (kinds.length !== Object.keys(ROOM_KINDS).length) fail('a room kind is missing from the room kind table');
  for (const set of Object.values(SETS)) {
    if (!kinds.some((k) => k.sets.includes(set))) fail(`set ${set} is in no room kind`);
    if (!questions.some((q) => q.set === set)) fail(`set ${set} has no questions`);
  }
}

const js = (value) => JSON.stringify(value).replaceAll("'", "\\'").replace(/^"(.*)"$/, "'$1'");

function coreModule({ questions, features, kinds }) {
  const lines = [
    `// ${GENERATED}`,
    '',
    '/** Question sets of rooms (specification 7.5), in catalog order. */',
    `export const SETS = [${Object.values(SETS).map(js).join(', ')}];`,
    '',
    '/** Room kinds and their sets; the order is the order of rooms in a Sweep (specification 7.5). */',
    'export const ROOM_KINDS = [',
    ...kinds.map((k) => `  { id: ${js(k.id)}, sets: [${k.sets.map(js).join(', ')}] },`),
    '];',
    '',
    '/** Switches (specification 7.6) in list order. A child switch only counts when its parent is on. */',
    'export const FEATURES = [',
    ...features.map((f) => `  { id: ${js(f.id)}, parent: ${f.parent ? js(f.parent) : 'null'} },`),
    '];',
    '',
    '/** Groups of questions outside rooms, in Sweep order, each with its switch. */',
    'export const GROUPS = [',
    ...Object.values(GROUPS).map((g) => `  { id: ${js(g)}, switch: ${js(features.find((f) => f.group === g).id)} },`),
    '];',
    '',
    '/**',
    ' * Questions in catalog order: id, task minutes, base interval in days, priority, stage, required switch,',
    ' * season [fromMonth, toMonth], in the first Sweep, and the set (room questions) or group.',
    ' */',
    'export const QUESTIONS = [',
    ...questions.map((q) => {
      const fields = [
        `id: ${js(q.id)}`,
        `minutes: ${q.minutes}`,
        `days: ${q.days}`,
        `priority: ${js(q.priority)}`,
        `stage: ${js(q.stage)}`,
        `requires: ${q.requires ? js(q.requires) : 'null'}`,
        `season: ${q.season ? `[${q.season[0]}, ${q.season[1]}]` : 'null'}`,
        `firstSweep: ${q.firstSweep}`,
        q.set ? `set: ${js(q.set)}` : 'set: null',
        q.group ? `group: ${js(q.group)}` : 'group: null',
      ];
      return `  { ${fields.join(', ')} },`;
    }),
    '];',
  ];
  return lines.join('\n') + '\n';
}

function textsModule({ questions, features, kinds }, lang) {
  const task = lang === 'pl' ? 'taskPl' : 'taskEn';
  const lines = [
    `// ${GENERATED}`,
    '',
    'export default {',
    '  /** Question id -> [question, task as a command]. */',
    '  questions: {',
    ...questions.map((q) => `    ${q.id}: [${js(q[lang])}, ${js(q[task])}],`),
    '  },',
    '  /** Room kind id -> name. */',
    '  roomKinds: {',
    ...kinds.map((k) => `    ${k.id}: ${js(k[lang])},`),
    '  },',
    '  /** Switch id -> name; a group is called like its switch. */',
    '  features: {',
    ...features.map((f) => `    ${f.id}: ${js(f[lang])},`),
    '  },',
    '};',
  ];
  return lines.join('\n') + '\n';
}

/** The generated files: path relative to the repository root -> contents. */
export async function generate() {
  const catalog = parse(await readFile(ROOT + SOURCE, 'utf8'));
  return {
    catalog,
    files: {
      'src/core/catalog-data.js': coreModule(catalog),
      'src/ui/i18n/catalog-en.js': textsModule(catalog, 'en'),
      'src/ui/i18n/catalog-pl.js': textsModule(catalog, 'pl'),
    },
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  try {
    const { catalog, files } = await generate();
    console.log(`${catalog.questions.length} questions, ${catalog.kinds.length} room kinds, ${catalog.features.length} switches`);
    for (const [path, text] of Object.entries(files)) {
      await writeFile(ROOT + path, text);
      console.log(`  -> ${path}`);
    }
  } catch (error) {
    if (!(error instanceof CatalogError)) throw error;
    console.error(error.message);
    process.exit(1);
  }
}
